-- Requires a privileged lab role; use a disposable database.
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'reporting_reader') THEN EXECUTE 'CREATE ROLE reporting_reader NOLOGIN'; END IF; END $$;
GRANT CONNECT ON DATABASE codeleaf_sql_lab TO reporting_reader;
GRANT USAGE ON SCHEMA public TO reporting_reader;
GRANT SELECT ON customers, orders TO reporting_reader;
